public class WatchTableFormatterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void finish() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    static java.util.List<String> list(String... values) {
        return new java.util.ArrayList<>(java.util.Arrays.asList(values));
    }

    public static void main(String[] args) {
        check("a short value is unchanged", "42", WatchTableFormatter.truncate("42"));
        check("null becomes a marker", "<null>", WatchTableFormatter.truncate(null));
        check("a 20 character value is kept", "01234567890123456789",
                WatchTableFormatter.truncate("01234567890123456789"));
        check("a 21 character value is cut", "01234567890123456...",
                WatchTableFormatter.truncate("012345678901234567890"));

        String expected = "i" + " ".repeat(11) + " = 3\n" + "names.size() = 7";
        check("two aligned rows", expected,
                WatchTableFormatter.format(list("i", "names.size()"), list("3", "7")));
        check("a single row needs no padding", "cart = <null>",
                WatchTableFormatter.format(list("cart"), list((String) null)));
        check("empty lists", "", WatchTableFormatter.format(list(), list()));

        String outcome = "no exception";
        try {
            WatchTableFormatter.format(list("i"), list("1", "2"));
        } catch (IllegalArgumentException e) {
            outcome = "IllegalArgumentException";
        } catch (RuntimeException e) {
            outcome = "wrong exception: " + e.getClass().getSimpleName();
        }
        check("mismatched sizes are rejected", "IllegalArgumentException", outcome);
        finish();
    }
}

