public class WatchTableFormatter {

    public static String truncate(String value) {
        if (value == null) {
            return "<null>";
        }
        if (value.length() <= 20) {
            return value;
        }
        return value.substring(0, 17) + "...";
    }

    public static String format(java.util.List<String> expressions, java.util.List<String> values) {
        if (expressions.size() != values.size()) {
            throw new IllegalArgumentException("expressions and values must be the same size");
        }
        int width = 0;
        for (String expression : expressions) {
            if (expression.length() > width) {
                width = expression.length();
            }
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < expressions.size(); i++) {
            if (i > 0) {
                out.append("\n");
            }
            String expression = expressions.get(i);
            out.append(expression)
               .append(" ".repeat(width - expression.length()))
               .append(" = ")
               .append(truncate(values.get(i)));
        }
        return out.toString();
    }
}
